package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.database.*;import java.io.*;import java.nio.file.*;import java.util.*;import org.json.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class) @LooperMode(LooperMode.Mode.PAUSED)
public class BookDuplicatesTest {
 Application app;StudyStore store;int next;
 @Before public void setup(){app=RuntimeEnvironment.getApplication();store=new StudyStore(app);}
 @After public void close(){store.close();BookDuplicates.RUNNING.set(false);}
 File file(String content)throws Exception{File f=new File(StudyFileProvider.directory(app),UUID.randomUUID()+".txt");Files.write(f.toPath(),content.getBytes("UTF-8"));return f;}
 long material(File f,String name,int progress)throws Exception{long group=store.save("subjects",0,StudyStore.values("title","Módulo "+(++next),"color",0,"created",1));return store.save("materials",0,StudyStore.values("subject",group,"title",name,"name",name+".txt","mime","text/plain","hash",StudyFiles.hash(f),"path",f.getPath(),"bytes",f.length(),"progress",progress,"created",1,"updated",1));}
 BookDuplicates.Result clean()throws Exception{return BookDuplicates.clean(app,store,()->false,name->{});}
 long visible(){BookQuery q=new BookQuery("",7,0,0,false,Collections.emptySet());return store.count("materials",q.where,q.args);}
 @Test public void identicalCopiesAreRemovedWithoutChangingCourseNotesBookmarksOrProgress()throws Exception{File a=file("Mesmo livro completo"),b=file("Mesmo livro completo");long x=material(a,"Livro antigo",20),y=material(b,"Outro nome",75);long note=store.save("notes",0,StudyStore.values("material",x,"title","Nota","body","Não perder","created",1,"updated",1));String oldUri=StudyFileProvider.uri(app,x).toString();try(ReaderStore reader=new ReaderStore(app)){reader.getWritableDatabase().insertOrThrow("bookmark",null,StudyStore.values("uri",oldUri,"segment",4,"position",12,"label","Marca","created",1));}app.getSharedPreferences("seeky",0).edit().putInt("reader_page_"+oldUri,4).commit();assertEquals(2,visible());BookDuplicates.Result r=clean();assertEquals(1,r.removed);assertEquals(b.length(),r.bytes);assertEquals(2,store.count("materials",null,null));assertEquals(1,visible());assertEquals(x,store.get("notes",note).n("material"));assertEquals(20,store.get("materials",x).n("progress"));assertEquals(75,store.get("materials",y).n("progress"));assertEquals(4,app.getSharedPreferences("seeky",0).getInt("reader_page_"+oldUri,0));try(ReaderStore reader=new ReaderStore(app);Cursor cursor=reader.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM bookmark WHERE uri=?",new String[]{oldUri})){cursor.moveToFirst();assertEquals(1,cursor.getInt(0));}assertEquals(store.get("materials",x).s("path"),store.get("materials",y).s("path"));assertTrue(new File(store.get("materials",x).s("path")).isFile());assertEquals(1,StudyFileProvider.directory(app).listFiles().length);assertEquals(0,clean().removed);}
 @Test public void sameNamesAndSameSizeWithDifferentContentsAreNeverRemoved()throws Exception{File a=file("AAAA"),b=file("BBBB");material(a,"Mesmo título",0);material(b,"Mesmo título",0);BookDuplicates.Result r=clean();assertEquals(0,r.removed);assertTrue(a.isFile());assertTrue(b.isFile());assertEquals(2,visible());}
 @Test public void staleStoredHashCannotMakeDifferentFilesDuplicates()throws Exception{File a=file("AAAA"),b=file("BBBB");long x=material(a,"A",0),y=material(b,"B",0);store.save("materials",y,StudyStore.values("hash",store.get("materials",x).s("hash")));BookDuplicates.Result r=clean();assertEquals(0,r.removed);assertTrue(r.issues>0);assertTrue(a.exists());assertTrue(b.exists());}
 @Test public void externalOriginalsAndSymlinksAreNeverDeleted()throws Exception{File a=file("Livro"),external=new File(app.getCacheDir(),"original.txt"),link=new File(StudyFileProvider.directory(app),"link.txt");Files.write(external.toPath(),"Livro".getBytes("UTF-8"));Files.createSymbolicLink(link.toPath(),external.toPath());material(a,"Privado",0);material(external,"Original",0);material(link,"Atalho",0);BookDuplicates.Result r=clean();assertEquals(0,r.removed);assertTrue(external.isFile());assertTrue(Files.isSymbolicLink(link.toPath()));assertTrue(a.isFile());}
 @Test public void cancellingScanKeepsAllUnconfirmedCopies()throws Exception{File a=file("Livro"),b=file("Livro");material(a,"A",0);material(b,"B",0);java.util.concurrent.atomic.AtomicBoolean stop=new java.util.concurrent.atomic.AtomicBoolean();BookDuplicates.Result r=BookDuplicates.clean(app,store,stop::get,name->stop.set(true));assertTrue(r.cancelled);assertEquals(0,r.removed);assertTrue(a.isFile());assertTrue(b.isFile());}
 @Test public void pendingCleanupAfterCommittedRelinkCanResumeSafely()throws Exception{File a=file("Livro"),b=file("Livro");material(a,"A",50);long y=material(b,"B",0);store.save("materials",y,StudyStore.values("path",a.getPath()));String entry=new JSONObject().put("from",b.getPath()).put("to",a.getPath()).put("hash",StudyFiles.hash(a)).toString();BookDuplicates.pending(app,new HashSet<>(Arrays.asList(entry)));BookDuplicates.Result r=clean();assertEquals(1,r.removed);assertFalse(b.exists());assertTrue(a.isFile());assertEquals(2,store.count("materials",null,null));assertTrue(app.getSharedPreferences("book_duplicates",0).getStringSet("pending",Collections.emptySet()).isEmpty());}
 @Test public void pendingCleanupNeverDeletesOnlyRemainingOrCurrentlyReferencedCopy()throws Exception{File a=file("Livro"),b=file("Livro");material(a,"A",0);long y=material(b,"B",0);String pending=new JSONObject().put("from",b.getPath()).put("to",a.getPath()).put("hash",StudyFiles.hash(a)).toString();Set<String> entries=new HashSet<>(Arrays.asList(pending));BookDuplicates.pending(app,entries);BookDuplicates.Result first=new BookDuplicates.Result();BookDuplicates.finishPending(app,store,entries,()->false,first);assertEquals(0,first.removed);assertTrue(b.isFile());store.save("materials",y,StudyStore.values("path",a.getPath()));a.delete();BookDuplicates.pending(app,new HashSet<>(Arrays.asList(pending)));BookDuplicates.Result r=clean();assertEquals(0,r.removed);assertTrue(b.isFile());assertTrue(r.issues>0);}
 @Test public void libraryProgressActionsApplyToSharedReferencesAndResetAllReaderPositions()throws Exception{File one=file("Livro"),two=file("Livro");long x=material(one,"A",40),y=material(two,"B",70);clean();String ux=StudyFileProvider.uri(app,x).toString(),uy=StudyFileProvider.uri(app,y).toString();app.getSharedPreferences("seeky",0).edit().putInt("reader_page_"+ux,4).putInt("reader_page_"+uy,8).commit();MainActivity a=Robolectric.buildActivity(MainActivity.class).get();a.prefs=a.getSharedPreferences("seeky",0);BookLibrary library=new BookLibrary(a);try{library.setProgress(store.get("materials",y),0);library.worker.submit(()->{}).get(10,java.util.concurrent.TimeUnit.SECONDS);org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals(0,store.get("materials",x).n("progress"));assertEquals(0,store.get("materials",y).n("progress"));assertEquals(0,app.getSharedPreferences("seeky",0).getInt("reader_page_"+ux,-1));assertEquals(0,app.getSharedPreferences("seeky",0).getInt("reader_page_"+uy,-1));assertEquals(1,visible());}finally{library.close();a.dead=true;a.worker.shutdown();a.finder.shutdown();a.searchJobs.close();}}
 @Test public void bookMenuProvidesWorkingDuplicateCleanup()throws Exception{File one=file("Livro"),two=file("Livro");material(one,"A",40);material(two,"B",70);MainActivity a=Robolectric.buildActivity(MainActivity.class).get();a.setTheme(android.R.style.Theme_Material_NoActionBar);a.prefs=a.getSharedPreferences("seeky",0);a.colors();a.studies=new StudyHub(a);BookLibrary library=new BookLibrary(a);a.books=library;try{library.menu();android.app.Dialog menu=org.robolectric.shadows.ShadowDialog.getLatestDialog();assertTrue(BooksToolsTest.labels(menu.getWindow().getDecorView()).contains("Verificar e remover duplicados"));menu.dismiss();library.duplicates();library.worker.submit(()->{}).get(10,java.util.concurrent.TimeUnit.SECONDS);org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals(1,visible());assertEquals(1,StudyFileProvider.directory(app).listFiles().length);}finally{UiDialog.dismissAll(a);UiPanel.dismissAll(a);library.close();a.studies.close();a.dead=true;a.worker.shutdown();a.finder.shutdown();a.searchJobs.close();}}
 @Test public void removingOneCourseReferenceDoesNotDeleteSharedBook()throws Exception{File a=file("Livro"),b=file("Livro");long x=material(a,"A",40),y=material(b,"B",50);clean();File kept=new File(store.get("materials",y).s("path"));BookDuplicates.removeMaterial(app,store,x);assertTrue(kept.exists());assertNotNull(store.get("materials",y));assertEquals(1,visible());BookDuplicates.removeMaterial(app,store,y);assertFalse(kept.exists());}
}
